-- ============================================================
-- Script registration
-- ============================================================
-- Negative ids = all ranks.  Registered on the two drain channels rather than
-- on the talent, because "while channeling" has no DBC representation:
--   -1120 = Drain Soul, -689 = Drain Life
--
-- Core already registers its own spell_warl_drain_soul on -1120; AzerothCore
-- allows several scripts per spell, so this is an additional row.  Delete by
-- ScriptName, never by spell_id.

DELETE FROM `spell_script_names` WHERE `ScriptName` = 'spell_warl_fel_concentration';
INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`) VALUES
(-1120, 'spell_warl_fel_concentration'),
(-689,  'spell_warl_fel_concentration');
